// app.component.ts
export class AppComponent {
  fullName = '';
  email = '';
  bio = '';
}

// app.component.html
<div>
  <input [(ngModel)]="fullName" placeholder="Full name">
  <input [(ngModel)]="email" placeholder="Email">
  <textarea [(ngModel)]="bio" placeholder="Bio"></textarea>
</div>

<div class="card">
  <h2>{{ fullName || 'Your Name' }}</h2>
  <p>{{ email || 'you@example.com' }}</p>
  <p>{{ bio || 'Tell us about yourself' }}</p>
</div>

// app.component.css (optional)
.card { border: 1px solid #ccc; padding: 1rem; margin-top: 1rem; border-radius: 8px; }

// app.module.ts must include FormsModule
